sys_script_include.script:
function GetLatestVersion(vVersions)
{
	var aVersions = GetArrayValue(vVersions);
	var aValidVersions = [];
	for (var nVersion = 0; nVersion < aVersions.length; nVersion++)
	{
		if (IsValidVersion(aVersions[nVersion]) == true)
		{
			aValidVersions.push(aVersions[nVersion]);
		}
	}
	if (aValidVersions.length == 0)
	{
		return false;
	}
	aValidVersions.sort(CompareVersion);
	return GetValue(aValidVersions,aValidVersions.length-1);
}
